const HTML="<!doctype html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#101813\"><title>Time Trial \u2014 Race Computer</title><style>\n:root{color-scheme:dark;--bg:#0c110e;--surface:#131d17;--line:#2c3d31;--ink:#edf8e9;--muted:#9dac9d;--lime:#c0f473;--red:#ffa69c}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px system-ui,sans-serif}button,input,select{font:inherit}button{cursor:pointer}button:disabled{opacity:.4;cursor:default}button,input,select{color:var(--ink);background:#19261e;border:1px solid var(--line);border-radius:7px;min-height:48px;padding:10px 14px}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid var(--lime);outline-offset:3px}header{border-bottom:1px solid var(--line);padding:20px 28px;display:flex;justify-content:space-between;gap:20px;align-items:center}.brand{font-size:24px;letter-spacing:-1px;font-weight:750}.brand span{color:var(--lime)}.label{font:11px monospace;letter-spacing:1.5px;color:var(--muted);text-transform:uppercase}.top{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.shell{max-width:1240px;margin:auto;padding:24px}.bar{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:24px;flex-wrap:wrap}nav{display:flex;gap:6px;flex-wrap:wrap}nav button{border-color:transparent;background:transparent;color:var(--muted)}nav button.active{color:var(--lime);background:#23331d;border-color:#415a2a}.status{font:12px monospace;color:var(--muted)}.grid{display:grid;grid-template-columns:minmax(280px,1.1fr) minmax(280px,.9fr);gap:24px}.panel{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:24px}h1{font-size:26px;letter-spacing:-.7px;margin:8px 0 20px}h2{font-size:18px;margin:0 0 18px}h3{font-size:15px}p{line-height:1.5}.number{font:700 112px/1 monospace;letter-spacing:-10px;margin:24px 0 10px;color:var(--lime)}.name{font-size:26px;font-weight:650}.metrics{display:flex;gap:28px;margin:25px 0;flex-wrap:wrap}.metrics strong{display:block;font:22px monospace;margin-top:7px}.primary{background:var(--lime);color:#14200d;border:0;font-weight:800}.capture{width:100%;min-height:126px;font:700 30px monospace;letter-spacing:1px}.finish{background:var(--red)}.secondary{width:100%;margin-top:14px}.row{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:15px 0;border-bottom:1px solid var(--line)}.row strong{font-family:monospace}.muted{color:var(--muted)}.small{font-size:12px}.tag{font:11px monospace;background:#263328;border-radius:4px;padding:5px 8px;white-space:nowrap}.feedback{min-height:26px;margin-top:16px;color:var(--lime);font:13px monospace}.queue{font-variant-numeric:tabular-nums}.queue button{min-width:112px}.choices{display:grid;grid-template-columns:repeat(auto-fit,minmax(125px,1fr));gap:9px;margin-top:12px}.choices button strong{display:block;font:24px monospace}.choices button small{display:block;margin-top:5px}input[type=search]{width:100%}.notice{border-left:3px solid var(--lime);padding:10px 16px;background:#1c281c;font-size:13px;margin-bottom:20px;color:#c4d3be}.warning{color:#ffd2a2}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px;font-variant-numeric:tabular-nums}th{text-align:left;font:11px monospace;letter-spacing:.4px;color:var(--muted);padding:13px 12px;border-bottom:1px solid var(--line);white-space:nowrap}td{padding:16px 12px;border-bottom:1px solid var(--line);white-space:nowrap}tbody tr:nth-child(even){background:#17221a}td small{display:block;margin-top:4px;color:var(--muted)}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px}.actions{display:flex;gap:10px;flex-wrap:wrap}.formgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:15px}label{display:block;font-size:12px;color:var(--muted)}label input,label select{display:block;width:100%;margin-top:7px}dialog{background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:12px;max-width:600px;width:calc(100% - 24px);padding:24px}dialog::backdrop{background:#000b}.close{float:right}.hidden{display:none!important}.mono{font-family:monospace}footer{padding:25px 0;color:var(--muted);font-size:12px;border-top:1px solid var(--line);margin-top:30px}#toast{position:fixed;bottom:20px;left:50%;transform:translateX(-50%);background:var(--lime);color:#14200d;padding:14px 20px;border-radius:8px;z-index:10;max-width:90%;box-shadow:0 5px 25px #0008}a{color:var(--lime)}@media(max-width:720px){header{padding:16px;align-items:flex-start;flex-direction:column;gap:12px}.shell{padding:14px}.grid{grid-template-columns:1fr;gap:14px}.panel{padding:18px}.number{font-size:94px}.top{width:100%}.top select{flex:1;min-width:0;max-width:100%}.bar{gap:12px}nav{width:100%;justify-content:space-between;gap:0}nav button{padding:10px;min-width:48px}.status{font-size:11px}.widecol{display:none}.capture{min-height:116px}th,td{padding:12px 7px}h1{font-size:23px}}@media(orientation:landscape) and (min-width:650px){.widecol{display:table-cell}}@media(prefers-reduced-motion:no-preference){.current{animation:rise .16s ease-out}@keyframes rise{from{transform:translateY(12px)}to{transform:translateY(0)}}}\n</style></head><body><header><div><div class=\"label\">Race timing / web edition</div><div class=\"brand\">TIME<span>TRIAL</span> <span style=\"font-weight:400;font-size:14px\">/ COMPUTER</span></div></div><div class=\"top\"><select id=\"race\" aria-label=\"Select race\"></select><select id=\"organiser\" aria-label=\"Recording organiser\"></select></div></header><div class=\"shell\"><div class=\"bar\"><nav aria-label=\"Main navigation\"><button data-page=\"start\" class=\"active\">Start</button><button data-page=\"lap\">Lap</button><button data-page=\"finish\">Finish</button><button data-page=\"results\">Results</button><button data-page=\"setup\">Setup</button></nav><div class=\"status\" id=\"connection\">Connecting\u2026</div></div><div class=\"notice\">TEST EDITION \u00b7 Synthetic race data. Shared saved records; 0.1-second display. Cross-device timing accuracy is not yet certified. Email and RiderHQ connections are not configured.</div><main id=\"main\"><p>Loading race records\u2026</p></main><footer>ONE PRESS. CAPTURE FIRST. ASSIGN AFTERWARDS. <span id=\"clock\" style=\"float:right\" class=\"mono\"></span></footer></div><dialog id=\"dialog\"></dialog><div id=\"toast\" role=\"status\" hidden></div><script src=\"/app.js\"></script></body></html>\n";
const APP="let seed,ops=[],pending=[],state,raceId,page='start',selectedCapture=null,filter='',sorting='actual',clockOffset=0,clockUncertainty=Infinity,db,feedback='',busy=false,expanded=new Set();\nconst $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c])),id=()=>crypto.randomUUID(),time=t=>t?new Date(t).toLocaleTimeString('en-GB',{hour12:false,fractionalSecondDigits:1}):'\u2014',dur=ms=>ms==null?'\u2014':(ms<0?'\u2212':'')+String(Math.floor(Math.abs(ms)/60000)).padStart(2,'0')+':'+(Math.floor(Math.abs(ms)/1000)%60).toString().padStart(2,'0')+'.'+Math.floor(Math.abs(ms)%1000/100),race=()=>state.races.find(r=>r.id===raceId),entries=()=>state.rider_entries.filter(e=>e.race_id===raceId).sort((a,b)=>a.planned_start_order-b.planned_start_order),rider=e=>state.riders.find(r=>r.id===e.rider_id),captures=e=>state.timing_captures.filter(c=>c.rider_entry_id===e.id&&!c.void).sort((a,b)=>a.race_timestamp.localeCompare(b.race_timestamp)),status=e=>{const c=captures(e),ev=state.rider_status_events.filter(s=>s.rider_entry_id===e.id).at(-1);return c.some(c=>c.type==='finish')?'Finished':ev?.event==='DNS'?'DNS':ev?.event==='DNF'?'DNF':c.some(c=>c.type==='start')?'Racing':'Waiting'},calc=e=>{const c=captures(e),s=c.find(c=>c.type==='start'),f=c.find(c=>c.type==='finish'),laps=c.filter(c=>c.type==='lap');const actual=s&&f?Date.parse(f.race_timestamp)-Date.parse(s.race_timestamp):null;return {s,f,laps,actual,adjusted:actual==null?null:actual-e.handicap_duration_ms}};\nfunction derive(){state=structuredClone(seed);for(const op of [...ops,...pending].filter((o,i,a)=>a.findIndex(x=>x.id===o.id)===i).sort((a,b)=>(a.server_time||a.created).localeCompare(b.server_time||b.created)||a.id.localeCompare(b.id))){const p=op.payload;if(op.type==='capture'&&!state.timing_captures.some(c=>c.id===p.id))state.timing_captures.push(p);if(op.type==='assign'){const c=state.timing_captures.find(c=>c.id===p.capture_id);if(c)c.rider_entry_id=p.entry_id}if(op.type==='void'){const c=state.timing_captures.find(c=>c.id===p.capture_id);if(c)c.void=true}if(op.type==='status')state.rider_status_events.push(p);if(op.type==='entry'){const e=state.rider_entries.find(e=>e.id===p.id);if(e)Object.assign(e,p)}if(op.type==='import'){state.riders.push(...p.riders);state.rider_entries.push(...p.entries)}}}\nasync function openDB(){db=await new Promise((res,rej)=>{const q=indexedDB.open('time-trial-queue',1);q.onupgradeneeded=()=>q.result.createObjectStore('pending',{keyPath:'id'});q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)});pending=await new Promise((res,rej)=>{const q=db.transaction('pending').objectStore('pending').getAll();q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)})}\nfunction durable(op,remove=false){return new Promise((res,rej)=>{const t=db.transaction('pending','readwrite');const s=t.objectStore('pending');remove?s.delete(op.id):s.put(op);t.oncomplete=res;t.onerror=()=>rej(t.error);t.onabort=()=>rej(t.error)})}\nfunction toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').hidden=true,3500)}\nasync function act(type,payload){const op={id:id(),type,payload,created:new Date().toISOString(),organiser_id:$('#organiser').value};try{await durable(op);pending.push(op);derive();render();sync();return true}catch(e){toast('Not saved \u2014 device storage error. Record a backup time.');return false}}\nasync function sync(){if(busy||!navigator.onLine)return;busy=true;try{for(const op of [...pending]){const res=await fetch('/api/events',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(op)});if(!res.ok){const body=await res.json();toast(body.error||'Sync rejected; retained locally');break}const saved=await res.json();await durable(op,true);pending=pending.filter(x=>x.id!==op.id);ops=ops.filter(x=>x.id!==op.id);ops.push(saved)}const res=await fetch('/api/events');if(!res.ok)throw Error();const fresh=await res.json();const changed=JSON.stringify(fresh)!==JSON.stringify(ops);ops=fresh;derive();updateConnection();if(changed&&!$('#dialog').open&&!document.activeElement?.matches('input'))render()}catch(e){$('#connection').textContent='Offline / sync delayed \u00b7 '+pending.length+' queued'}finally{busy=false}}\nasync function calibrate(){const samples=[];for(let i=0;i<5;i++){const a=performance.timeOrigin+performance.now();try{const r=await fetch('/api/time',{cache:'no-store'});const b=await r.json();const z=performance.timeOrigin+performance.now();samples.push({offset:b.now-(a+z)/2,uncertainty:(z-a)/2})}catch{}}samples.sort((a,b)=>a.uncertainty-b.uncertainty);if(samples.length){clockOffset=samples[0].offset;clockUncertainty=samples[0].uncertainty}updateConnection()}\nfunction nowStamp(event){const raw=event?.timeStamp;const t=raw>1e12?raw:raw>0?performance.timeOrigin+raw:performance.timeOrigin+performance.now();return {original:new Date(t).toISOString(),race:new Date(t+clockOffset).toISOString()}}\nfunction updateConnection(){$('#connection').textContent=(navigator.onLine?'\u25cf ONLINE':'\u25cb OFFLINE')+' \u00b7 '+pending.length+' queued \u00b7 clock \u00b1'+(isFinite(clockUncertainty)?Math.ceil(clockUncertainty)+' ms':'unknown')}\nfunction capture(type,event,entry=null){const at=nowStamp(event);const p={id:id(),race_id:raceId,station_id:raceId+'-'+type,session_id:sessionStorage.ttDevice||(sessionStorage.ttDevice=id()),type,original_device_timestamp:at.original,race_timestamp:at.race,rider_entry_id:entry?.id||null,clock_uncertainty_ms:isFinite(clockUncertainty)?clockUncertainty:null,assignment_state:entry?'assigned':'unassigned'};feedback=(entry?'#'+entry.rider_number+' started':'Capture saved')+' \u00b7 '+time(at.race);act('capture',p).then(ok=>{if(ok&&navigator.vibrate)navigator.vibrate(30)})}\nfunction render(){if(!state)return;$('#race').innerHTML=state.races.map(r=>'<option value=\"'+r.id+'\" '+(r.id===raceId?'selected':'')+'>'+esc(r.name)+'</option>').join('');$('#organiser').innerHTML=state.organisers.map(o=>'<option value=\"'+o.id+'\" '+(o.id===localStorage.ttOrg?'selected':'')+'>'+esc(o.display_name)+'</option>').join('');document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#main').innerHTML=page==='start'?startHTML():['lap','finish'].includes(page)?captureHTML():page==='results'?resultsHTML():setupHTML();bind();updateConnection()}\nfunction startHTML(){const es=entries(),current=es.find(e=>status(e)==='Waiting'),done=es.filter(e=>status(e)!=='Waiting');return '<div class=\"grid\"><section class=\"panel\"><div class=\"label\">START STATION / NEXT RIDER</div><div class=\"current\" key=\"'+(current?.id||'end')+'\"><div class=\"number\">'+(current?esc(current.rider_number):'\u2713')+'</div><div class=\"name\">'+(current?esc(rider(current).name):'Start queue complete')+'</div></div><div class=\"metrics\"><div><span class=\"label\">Start order</span><strong>'+(current?.planned_start_order||'\u2014')+'</strong></div><div><span class=\"label\">Prediction</span><strong>'+dur(current?.predicted_duration_ms)+'</strong></div><div><span class=\"label\">Handicap</span><strong>'+dur(current?.handicap_duration_ms)+'</strong></div></div><button id=\"startBtn\" class=\"primary capture\" '+(!current?'disabled':'')+'>START '+(current?'#'+current.rider_number:'COMPLETE')+' \u2192</button><button id=\"dnsBtn\" class=\"secondary\" '+(!current?'disabled':'')+'>DNS \u2014 SKIP ABSENT RIDER</button><div class=\"feedback\" aria-live=\"polite\">'+esc(feedback||'READY FOR START')+'</div></section><section class=\"panel\"><h2>Start queue <span class=\"muted\">/ '+es.filter(e=>status(e)==='Waiting').length+' waiting</span></h2>'+es.filter(e=>status(e)==='Waiting').slice(1,7).map(e=>'<div class=\"row\"><div><strong>#'+e.rider_number+'</strong> '+esc(rider(e).name)+'</div><span class=\"tag\">ORDER '+e.planned_start_order+'</span></div>').join('')+'<h3>Recently processed</h3>'+done.slice(-5).reverse().map(e=>'<div class=\"row small\"><span>#'+e.rider_number+' '+esc(rider(e).name)+'</span><span class=\"tag\">'+status(e)+'</span></div>').join('')+'</section></div>'}\nfunction captureHTML(){const cs=state.timing_captures.filter(c=>c.race_id===raceId&&c.type===page&&!c.void),unassigned=cs.filter(c=>!c.rider_entry_id).sort((a,b)=>a.race_timestamp.localeCompare(b.race_timestamp)),selected=cs.find(c=>c.id===selectedCapture);return '<div class=\"grid\"><section class=\"panel\"><div class=\"label\">'+page.toUpperCase()+' STATION'+(page==='lap'?' / SINGLE CHECKPOINT':'')+'</div><h1>'+(page==='lap'?'Every lap. One press.':'At the line. One press.')+'</h1><p class=\"muted\">Capture the crossing first.<br>Attach the rider when you are ready.</p><button class=\"primary capture '+(page==='finish'?'finish':'')+'\" id=\"captureBtn\">'+page.toUpperCase()+' \uff0b</button><div class=\"feedback\" aria-live=\"polite\">'+esc(feedback||'READY TO CAPTURE')+'</div><div class=\"metrics\"><div><span class=\"label\">Unassigned</span><strong>'+unassigned.length+'</strong></div><div><span class=\"label\">Recorded</span><strong>'+cs.length+'</strong></div></div><h3>Recent assigned captures</h3>'+cs.filter(c=>c.rider_entry_id).slice(-4).reverse().map(c=>{const e=state.rider_entries.find(e=>e.id===c.rider_entry_id);return '<div class=\"row small\"><span>'+time(c.race_timestamp)+' \u2192 #'+e?.rider_number+'</span><button data-assign=\"'+c.id+'\">Correct</button></div>'}).join('')+'</section><section class=\"panel\"><h2>Capture queue <span class=\"muted\">/ '+unassigned.length+'</span></h2><div class=\"queue\">'+(unassigned.map((c,i)=>'<div class=\"row\"><div><span class=\"label\">CAPTURE '+(i+1)+'</span><br><strong>'+time(c.race_timestamp)+'</strong></div><button data-assign=\"'+c.id+'\" '+(selected?.id===c.id?'class=\"primary\"':'')+'>Assign rider</button><button data-void=\"'+c.id+'\" aria-label=\"Void capture at '+time(c.race_timestamp)+'\">\u00d7</button></div>').join('')||'<p class=\"muted\">All captured times assigned.</p>')+'</div>'+(selected?'<h3>Assign '+time(selected.race_timestamp)+'</h3><input type=\"search\" id=\"riderSearch\" placeholder=\"Rider number or name\" value=\"'+esc(filter)+'\"><div class=\"choices\" id=\"choices\">'+choicesHTML(selected)+'</div>':'<p class=\"small muted\">Press '+page.toUpperCase()+' for every passing rider. Unassigned times stay here until matched.</p>')+'</section></div>'}\nfunction choicesHTML(c){return entries().filter(e=>(status(e)==='Racing'||c.rider_entry_id===e.id)&&('#'+e.rider_number+' '+rider(e).name).toLowerCase().includes(filter.toLowerCase())).map(e=>'<button data-rider=\"'+e.id+'\"><strong>#'+e.rider_number+'</strong><small>'+esc(rider(e).name)+'</small><small>'+calc(e).laps.length+' laps</small></button>').join('')||'<p class=\"warning\">No eligible riders. Start a rider or check the race selection.</p>'}\nfunction ranked(){const es=entries().map(e=>({...e,...calc(e),rider:rider(e),status:status(e)}));const finish=es.filter(e=>e.actual!=null);for(const key of ['actual','adjusted']){const vals=finish.map(e=>Math.round(e[key]/100)).sort((a,b)=>a-b);finish.forEach(e=>e[key+'Pos']=vals.indexOf(Math.round(e[key]/100))+1)}finish.sort((a,b)=>a.f.race_timestamp.localeCompare(b.f.race_timestamp)).forEach((e,i)=>e.crossing=i+1);return es.sort((a,b)=>sorting==='order'?a.planned_start_order-b.planned_start_order:sorting==='finish'?(a.crossing??Infinity)-(b.crossing??Infinity):(a[sorting]??Infinity)-(b[sorting]??Infinity))}\nfunction resultsHTML(){const data=ranked();return '<section class=\"panel\"><div class=\"bar\"><div><div class=\"label\">RACE CONTROL / PROVISIONAL</div><h1>'+esc(race().name)+'</h1></div><div class=\"actions\"><button id=\"export\">Export CSV</button><button id=\"publish\" class=\"primary\">Publish results & email</button></div></div><div class=\"toolbar\"><select id=\"sort\" aria-label=\"Sort results\">'+[['actual','Actual duration'],['adjusted','Adjusted duration'],['finish','Finish crossing'],['order','Start order']].map(([v,t])=>'<option value=\"'+v+'\" '+(sorting===v?'selected':'')+'>'+t+'</option>').join('')+'</select><span class=\"status\">'+data.filter(e=>e.status==='Racing').length+' racing \u00b7 '+data.filter(e=>e.status==='Finished').length+' finished \u00b7 '+data.filter(e=>e.status==='DNS').length+' DNS</span></div><div class=\"table-wrap\"><table><thead><tr><th>Rider / status</th><th>Actual / place</th><th>Adjusted / place</th><th class=\"widecol\">Handicap</th><th class=\"widecol\">Laps</th><th class=\"widecol\">Start</th><th class=\"widecol\">Finish / sequence</th></tr></thead><tbody>'+data.map(e=>'<tr data-detail=\"'+e.id+'\" style=\"cursor:pointer\"><td><strong>#'+e.rider_number+' '+esc(e.rider.name)+'</strong><small>'+e.status+' \u00b7 view details</small></td><td>'+dur(e.actual)+'<small>'+(e.actualPos?'#'+e.actualPos:'\u2014')+'</small></td><td>'+dur(e.adjusted)+'<small>'+(e.adjustedPos?'#'+e.adjustedPos:'\u2014')+'</small></td><td class=\"widecol\">'+dur(e.handicap_duration_ms)+'</td><td class=\"widecol\">'+e.laps.length+'</td><td class=\"widecol\">'+time(e.s?.race_timestamp)+'</td><td class=\"widecol\">'+time(e.f?.race_timestamp)+'<small>'+(e.crossing?'Crossing '+e.crossing:'\u2014')+'</small></td></tr>'+(expanded.has(e.id)?'<tr><td colspan=\"7\"><div class=\"small\">Start '+time(e.s?.race_timestamp)+' \u00b7 Finish '+time(e.f?.race_timestamp)+' \u00b7 Prediction '+dur(e.predicted_duration_ms)+' \u00b7 Handicap '+dur(e.handicap_duration_ms)+'<br>'+e.laps.map((l,i)=>'Lap '+(i+1)+' '+time(l.race_timestamp)+' / split '+dur(Date.parse(l.race_timestamp)-Date.parse((i?e.laps[i-1]:e.s)?.race_timestamp))).join(' \u00b7 ')+'</div></td></tr>':'')).join('')+'</tbody></table></div></section>'}\nfunction setupHTML(){return '<section class=\"panel\"><div class=\"bar\"><div><div class=\"label\">RACE CONFIGURATION</div><h1>Ready before race day.</h1></div><button id=\"importBtn\" class=\"primary\">Import CSV</button></div><p class=\"muted\">'+esc(race().start_location)+' \u00b7 '+esc(race().route_name)+' \u00b7 '+race().date+' \u00b7 Europe/London</p><p class=\"small\">One lap checkpoint, repeated on successive laps. Separate Start and Finish stations.</p><div class=\"toolbar\"><button id=\"template\">CSV template</button><button id=\"backup\">Download full backup</button><button id=\"rhq\">RiderHQ connection</button></div><div class=\"table-wrap\"><table><thead><tr><th>Order</th><th>Rider</th><th>Prediction</th><th>Handicap</th><th>Email</th><th>Edit</th></tr></thead><tbody>'+entries().map(e=>'<tr><td>'+e.planned_start_order+'</td><td>#'+e.rider_number+' '+esc(rider(e).name)+'</td><td>'+dur(e.predicted_duration_ms)+'</td><td>'+dur(e.handicap_duration_ms)+'</td><td>'+esc(rider(e).email)+'</td><td><button data-edit=\"'+e.id+'\">Edit</button></td></tr>').join('')+'</tbody></table></div><p class=\"small muted\">Synthetic organiser selection is for test attribution. Private owner access is enforced by hosting; volunteer invitations are not yet enabled.</p></section>'}\nfunction dialog(html){$('#dialog').innerHTML='<button class=\"close\" id=\"closeDialog\" aria-label=\"Close dialog\">\u00d7</button>'+html;$('#dialog').showModal();$('#closeDialog').onclick=()=>$('#dialog').close()}\nfunction bindChoices(){document.querySelectorAll('[data-rider]').forEach(b=>b.onclick=async()=>{const c=state.timing_captures.find(x=>x.id===selectedCapture);if(!c)return;await act('assign',{capture_id:c.id,entry_id:b.dataset.rider,previous_entry_id:c.rider_entry_id||null});selectedCapture=null;filter='';render()})}\nfunction bind(){if($('#startBtn')){$('#startBtn').onpointerdown=e=>{e.preventDefault();const en=entries().find(x=>status(x)==='Waiting');if(en){e.currentTarget.disabled=true;capture('start',e,en)}};$('#startBtn').onkeydown=e=>{if(['Enter',' '].includes(e.key)&&!e.repeat){e.preventDefault();const en=entries().find(x=>status(x)==='Waiting');if(en)capture('start',e,en)}};$('#dnsBtn').onclick=()=>{const e=entries().find(e=>status(e)==='Waiting');if(e){feedback='#'+e.rider_number+' marked DNS';act('status',{id:id(),rider_entry_id:e.id,event:'DNS',timestamp:new Date().toISOString()})}}}if($('#captureBtn')){$('#captureBtn').onpointerdown=e=>{e.preventDefault();capture(page,e)};$('#captureBtn').onkeydown=e=>{if(['Enter',' '].includes(e.key)&&!e.repeat){e.preventDefault();capture(page,e)}}}document.querySelectorAll('[data-assign]').forEach(b=>b.onclick=()=>{selectedCapture=b.dataset.assign;filter='';render()});document.querySelectorAll('[data-void]').forEach(b=>b.onclick=()=>{dialog('<h2>Void accidental capture?</h2><p>The original timestamp remains in the audit history.</p><label>Reason<input id=\"reason\" required value=\"Accidental press\"></label><button class=\"primary\" id=\"confirmVoid\">Void capture</button>');$('#confirmVoid').onclick=async()=>{if(!$('#reason').value.trim())return;await act('void',{capture_id:b.dataset.void,reason:$('#reason').value.trim()});$('#dialog').close()}});if($('#riderSearch'))$('#riderSearch').oninput=e=>{filter=e.target.value;$('#choices').innerHTML=choicesHTML(state.timing_captures.find(c=>c.id===selectedCapture));bindChoices()};bindChoices();document.querySelectorAll('[data-detail]').forEach(el=>el.onclick=()=>{expanded.has(el.dataset.detail)?expanded.delete(el.dataset.detail):expanded.add(el.dataset.detail);render()});if($('#sort'))$('#sort').onchange=e=>{sorting=e.target.value;render()};if($('#export'))$('#export').onclick=exportCSV;if($('#publish'))$('#publish').onclick=()=>{const missing=entries().filter(e=>!rider(e).email).length,unassigned=state.timing_captures.filter(c=>c.race_id===raceId&&!c.rider_entry_id&&!c.void).length;dialog('<h2>Publication readiness</h2><p>'+unassigned+' unassigned captures \u00b7 '+missing+' missing rider emails \u00b7 '+pending.length+' unsynchronised changes.</p><p class=\"warning\">Email delivery is not configured. Nothing will be sent. Synthetic addresses cannot receive email.</p><p>Export the provisional results CSV for review.</p><button id=\"reviewExport\" class=\"primary\">Download results CSV</button>');$('#reviewExport').onclick=exportCSV};document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editEntry(b.dataset.edit));if($('#importBtn'))$('#importBtn').onclick=importDialog;if($('#template'))$('#template').onclick=()=>download('rider-import-template.csv','name,rider_number,gender,age,email,predicted_duration,start_order,handicap\\r\\nAlex Example,101,Female,35,alex@example.invalid,25:00,21,01:30\\r\\n','text/csv');if($('#backup'))$('#backup').onclick=()=>download('time-trial-backup.json',JSON.stringify({seed,events:ops,pending},null,2),'application/json');if($('#rhq'))$('#rhq').onclick=()=>dialog('<h2>RiderHQ</h2><p>Direct import is pending RiderHQ API documentation and authorisation. Use CSV export from RiderHQ, then Import CSV here.</p><p>No account credentials are collected.</p>')}\nfunction editEntry(eid){const e=state.rider_entries.find(e=>e.id===eid);dialog('<h2>Edit #'+e.rider_number+' '+esc(rider(e).name)+'</h2><div class=\"formgrid\"><label>Start order<input id=\"order\" type=\"number\" min=\"1\" value=\"'+e.planned_start_order+'\"></label><label>Predicted duration (mm:ss)<input id=\"prediction\" value=\"'+dur(e.predicted_duration_ms).split('.')[0]+'\"></label><label>Handicap minutes<input id=\"hm\" type=\"number\" min=\"0\" value=\"'+Math.floor(e.handicap_duration_ms/60000)+'\"></label><label>Handicap seconds<input id=\"hs\" type=\"number\" min=\"0\" max=\"59\" value=\"'+e.handicap_duration_ms/1000%60+'\"></label></div><p id=\"editError\" class=\"warning\" role=\"alert\"></p><button class=\"primary\" id=\"saveEntry\">Save entry</button>');$('#saveEntry').onclick=async()=>{const order=Number($('#order').value),m=Number($('#hm').value),s=Number($('#hs').value),pred=parseDuration($('#prediction').value);if(!Number.isInteger(order)||order<1||entries().some(x=>x.id!==eid&&x.planned_start_order===order))return $('#editError').textContent='Choose a unique positive start order.';if(!Number.isInteger(m)||!Number.isInteger(s)||m<0||s<0||s>59||pred===null)return $('#editError').textContent='Check prediction and handicap (seconds 00\u201359).';await act('entry',{id:eid,planned_start_order:order,handicap_duration_ms:(m*60+s)*1000,predicted_duration_ms:pred});$('#dialog').close()}}\nfunction download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}\nconst csvCell=x=>{let s=String(x??'');if(/^[=+@\\t\\r]/.test(s))s=\"'\"+s;return '\"'+s.replace(/\"/g,'\"\"')+'\"'};\nfunction exportCSV(){const rows=[['race','date','route','start_location','rider_number','name','gender','age','status','start_order','start_timestamp','lap_crossings_json','finish_timestamp','finish_crossing_sequence','actual_duration','actual_position','handicap','adjusted_duration','adjusted_position','predicted_duration']];for(const e of ranked())rows.push([race().name,race().date,race().route_name,race().start_location,e.rider_number,e.rider.name,e.rider.gender,e.age_on_race_day,e.status,e.planned_start_order,e.s?.race_timestamp,JSON.stringify(e.laps.map(c=>c.race_timestamp)),e.f?.race_timestamp,e.crossing,dur(e.actual),e.actualPos,dur(e.handicap_duration_ms),dur(e.adjusted),e.adjustedPos,dur(e.predicted_duration_ms)]);download('provisional-results.csv',rows.map(r=>r.map(csvCell).join(',')).join('\\r\\n'),'text/csv;charset=utf-8')}\nfunction parseDuration(v){if(!/^\\d+:\\d{2}(\\.\\d)?$/.test(v))return null;const [m,s]=v.split(':');return Number(s)<60?(Number(m)*60+Number(s))*1000:null}\nfunction parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='\"'){if(quoted&&text[i+1]==='\"'){cell+='\"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\\n'||c==='\\r')&&!quoted){if(c==='\\r'&&text[i+1]==='\\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('Unclosed quoted field');if(cell||row.length){row.push(cell);rows.push(row)}return rows}\nfunction importDialog(){dialog('<h2>Import rider entries</h2><p class=\"small muted\">CSV columns: name, rider_number, gender, age, email, predicted_duration, start_order, handicap. Add-new entries only; duplicate numbers are rejected.</p><input type=\"file\" id=\"csvFile\" accept=\".csv,text/csv\"><div id=\"importPreview\"></div>');$('#csvFile').onchange=async ev=>{try{const file=ev.target.files[0];if(file.size>2000000)throw Error('Maximum CSV size is 2 MB');const rows=parseCSV((await file.text()).replace(/^\\uFEFF/,''));const headers=rows.shift().map(h=>h.trim().toLowerCase());if(!headers.includes('name')||!headers.includes('rider_number'))throw Error('name and rider_number headers required');const errors=[],newRiders=[],newEntries=[],nums=new Set(entries().map(e=>String(e.rider_number))),orders=new Set(entries().map(e=>e.planned_start_order));let next=Math.max(0,...orders)+1;for(const [i,row]of rows.entries()){const o=Object.fromEntries(headers.map((h,j)=>[h,(row[j]||'').trim()]));let err=[];if(!o.name)err.push('name missing');if(!/^\\d+$/.test(o.rider_number)||nums.has(o.rider_number))err.push('invalid/duplicate rider number');nums.add(o.rider_number);const order=o.start_order?Number(o.start_order):next++;if(!Number.isInteger(order)||order<1||orders.has(order))err.push('invalid/duplicate order');orders.add(order);const handicap=parseDuration(o.handicap||'00:00'),pred=parseDuration(o.predicted_duration||'25:00');if(handicap===null||pred===null)err.push('duration must be mm:ss');if(o.age&&(!/^\\d+$/.test(o.age)||Number(o.age)>120))err.push('invalid age');if(o.email&&!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(o.email))err.push('invalid email');if(err.length)errors.push('Row '+(i+2)+': '+err.join(', '));const rid=id();newRiders.push({id:rid,name:o.name,gender:o.gender||null,age:o.age?Number(o.age):null,email:o.email||null});newEntries.push({id:id(),race_id:raceId,rider_id:rid,rider_number:Number(o.rider_number),age_on_race_day:o.age?Number(o.age):null,predicted_duration_ms:pred,handicap_duration_ms:handicap,planned_start_order:order})}$('#importPreview').innerHTML='<p>'+rows.length+' rows \u00b7 '+errors.length+' errors</p>'+errors.map(e=>'<p class=\"warning\">'+esc(e)+'</p>').join('')+'<p>'+newRiders.slice(0,5).map(r=>esc(r.name)).join(' \u00b7 ')+'</p><button id=\"confirmImport\" class=\"primary\" '+(errors.length||!rows.length?'disabled':'')+'>Import '+rows.length+' entries</button>';$('#confirmImport').onclick=async()=>{await act('import',{riders:newRiders,entries:newEntries});$('#dialog').close();toast('Entries saved; syncing')}}catch(e){$('#importPreview').textContent=e.message}}}\n$('#race').onchange=e=>{raceId=e.target.value;localStorage.ttRace=raceId;selectedCapture=null;feedback='';render()};$('#organiser').onchange=e=>localStorage.ttOrg=e.target.value;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;selectedCapture=null;filter='';feedback='';render()});window.addEventListener('online',sync);window.addEventListener('offline',updateConnection);setInterval(()=>$('#clock').textContent=time(new Date().toISOString()),100);setInterval(sync,2500);setInterval(calibrate,60000);\n(async()=>{try{await openDB();const res=await fetch('/api/seed');if(!res.ok)throw Error('Cannot load shared race data');seed=await res.json();raceId=localStorage.ttRace||seed.races[1].id;if(!seed.races.some(r=>r.id===raceId))raceId=seed.races[0].id;derive();render();await calibrate();await sync()}catch(e){$('#main').textContent='Unable to load: '+e.message+'. Please reload when connected.'}})();\n";
